/* Generated by port_pages.py from the approved mockup. Behaviour for the features page; timers, listeners and observers go through ctx. */
export function init(ctx) {
  var reduce = ctx.reduce;

  [].forEach.call(document.querySelectorAll(".fx a"), function (a) {
    ctx.on(a, "click", function (e) {
      e.preventDefault();
      var t = document.querySelector(a.getAttribute("href"));
      if (t)
        window.scrollTo({
          top: t.getBoundingClientRect().top + window.scrollY - 80,
          behavior: reduce ? "auto" : "smooth",
        });
    });
  });
  var links = [].slice.call(document.querySelectorAll(".fx a")),
    mods = [].slice.call(document.querySelectorAll(".fm")),
    fx = document.getElementById("fx");
  function mark(k) {
    links.forEach(function (a) {
      var on = a.dataset.k === k;
      a.classList.toggle("on", on);
      if (on && fx.scrollWidth > fx.clientWidth)
        fx.scrollTo({
          left: a.offsetLeft - 16,
          behavior: reduce ? "auto" : "smooth",
        });
    });
  }
  if (!("IntersectionObserver" in window)) {
    mods.forEach(function (m) {
      m.classList.add("seen");
    });
    return;
  }
  /* the module crossing the middle of the screen is the active one; its window rises in once */
  var spy = ctx.io(
    function (es) {
      es.forEach(function (e) {
        if (e.isIntersecting) mark(e.target.dataset.k);
      });
    },
    { rootMargin: "-45% 0px -50% 0px" },
  );
  var rise = ctx.io(
    function (es) {
      es.forEach(function (e) {
        if (e.isIntersecting) {
          e.target.classList.add("seen");
          rise.unobserve(e.target);
        }
      });
    },
    { threshold: 0.2 },
  );
  mods.forEach(function (m) {
    spy.observe(m);
    rise.observe(m);
  });
}
